def relu(x):
    return x if x > 0 else 0

for value in [-3, -0.5, 0, 2, 7]:
    print(f"relu({value}) = {relu(value)}")

def loss(x):
    # яма с минимумом в x = 3
    return (x - 3) ** 2

def slope(f, x, h=1e-6):
    return (f(x + h) - f(x)) / h

x = 10.0
rate = 0.1

for step in range(1, 21):
    g = slope(loss, x)
    x = x - rate * g
    if step % 4 == 0:
        print(f"шаг {step:2}: x = {x:.4f}, потери = {loss(x):.6f}")

print(f"итог: x ≈ {x:.3f} (минимум в 3)")
